while ($true) { $r=Test-Connection 1.1.1.1 -Count 1 -ErrorAction SilentlyContinue; if ($r) { $t=$r.ResponseTime; if ($t -lt 50) { Write-Host "Reply from 1.1.1.1: time=${t}ms" -ForegroundColor Green } elseif ($t -lt 100) { Write-Host "Reply from 1.1.1.1: time=${t}ms" -ForegroundColor Yellow } else { Write-Host "Reply from 1.1.1.1: time=${t}ms" -ForegroundColor Red } } else { Write-Host "Ping failed" -ForegroundColor DarkRed }; Start-Sleep -Seconds 1 }
